{"script": "python3 << 'EOF'
import FreeCAD
import Part

# Open the precondition file
doc = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")

# Get the sketch object
sketch = doc.getObject("Sketch")

# Print all attributes of the sketch
print("Sketch attributes:")
for attr in dir(sketch):
    if not attr.startswith('_'):
        try:
            val = getattr(sketch, attr)
            if not callable(val):
                print(f"  {attr}: {val}")
        except:
            pass

# Try to get the external references
print("\nExternal references:")
if hasattr(sketch, 'ExternalGeometry'):
    print(f"  ExternalGeometry: {sketch.ExternalGeometry}")

FreeCAD.closeDocument(doc.Name)
EOF"}
